WITH unpacked AS (SELECT id, service, host, level, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, COALESCE(context['region'], 'direct') AS region_or_default, SHIFTRIGHT(status_code, 2) AS status_code_high, COALESCE(context['trace'], 'direct') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT *, SUM(retry_count) OVER (ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_retry_count, NTILE(3) OVER (PARTITION BY level ORDER BY latency_ms, id) AS latency_ms_bucket, AVG(latency_ms) OVER (ORDER BY latency_ms, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS latency_ms_avg_3_prior FROM unpacked;
